  /// Total number of messages decoded, across every type.
  int get length {
    var total = 0;
    for (final list in _allLists) {
      total += list.length;
    }
    return total;
  }

  /// Every decoded message, grouped by type rather than in file order.
  List<Mesg> all() {
    final result = <Mesg>[];
    for (final list in _allLists) {
      result.addAll(list);
    }
    return result;
  }
